// Portfolio content, bilingual. Facts come from the Behance project data, the project images and Or's CV.
// The content itself lives in content/projects.json (editable in Pages CMS — see .pages.yml); array order = order on
// the site, following Or's Behance profile. Image ids refer to src/data/images.json (generated by scripts/images.mjs).
import type { T } from '../i18n';
import projectData from '../content/projects.json';

export type Img = { id: string; alt: T };
export type Detail = { label: T; body: T; colors?: string[] };

export type Project = {
  slug: string;
  title: T;
  subtitle: T;
  client: T;
  year: string;
  discipline: T[];
  tools: string[];
  accent: string; // taken from each project's own palette
  cover: Img; // home page
  hero: Img; // top of the project page
  intro: T[];
  details?: Detail[];
  gallery: Img[]; // laid out automatically: wide images full width, tall/square images in rows
  behance: string;
};

export const projects = projectData as Project[];

export const bySlug = (slug: string) => projects.find((p) => p.slug === slug);
